export type TreeNode = {
  id: string;
  type: "TRACE" | ObservationType;
  name: string;
  startTime: Date;
  endTime?: Date | null;
  level?: string;
  children: TreeNode[];
  // Token usage
  inputUsage?: number | null;
  outputUsage?: number | null;
  totalUsage?: number | null;
  // Per-node cost from API
  calculatedInputCost?: number | null;
  calculatedOutputCost?: number | null;
  calculatedTotalCost?: number | null;
  // Pre-computed cost for this node + all descendants
  // Calculated bottom-up during tree construction for O(1) access
  totalCost?: Decimal;
  // Duration in seconds. Set on TRACE wrapper nodes (v3) or root observation nodes (v4 events-based traces).
  latency?: number;
  // Wall-clock duration of this node's subtree, in milliseconds:
  // max(end time) − min(start time) across this node and ALL its descendants.
  // Calculated bottom-up during tree construction (mirrors totalCost). Lets the UI
  // surface async children that outlive their parent span, whose own
